        SET @NewUserId = CAST(SCOPE_IDENTITY() AS INT);

        INSERT INTO dbo.SERVICE_PROVIDERS (USER_ID, BUSINESS_NAME, DESCRIPTION, ADDRESS, BASE_FEE,
                                           AVG_RATING, REVIEW_COUNT, MIN_NOTICE_DAYS, MAX_JOBS_PER_DAY,
